saldo = 'muito';
// Erro: Type 'string' is not
// assignable to type 'number'`},{t:"Tipos básicos: a anotação",txt:"A anotação vai depois do nome, com dois pontos: string, number, boolean, e arrays com tipo[]. Na maioria das vezes o TS INFERE sozinho pelo valor — mas saber anotar é a base.",code:`const nome: string = 'Edu';
